style.css:
@-moz-document url-prefix("https://www.youtube.com/") {
/* Main wallpaper: https://chatgpt.com/backend-api/estuary/content?id=file-MWyc9p28SWJZi8o5zrX5mt&ts=488226&p=fs&cid=1&sig=659e9dafa025ffdd07757af44f52589a219f7f214308f361bbbdcc78098844d8&v=0 */
  html, body, ytd-app, #page-manager {
    background-image: url(https://chatgpt.com/backend-api/estuary/content?id=file-MWyc9p28SWJZi8o5zrX5mt&ts=488226&p=fs&cid=1&sig=659e9dafa025ffdd07757af44f52589a219f7f214308f361bbbdcc78098844d8&v=0) !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-size: cover !important;
  }

  /* Make main content panels transparent so the wallpaper shows through */
  ytd-app, #page-manager, #content, #columns, #primary, #secondary, #columns ytd-rich-grid-renderer,
  ytd-browse, ytd-watch-flexy, ytd-rich-grid-renderer, ytd-rich-item-renderer {
    background: transparent !important;
  }

  /* So the header / search bar is readable: add a subtle translucent bar */
  #masthead-container, ytd-masthead, ytd-masthead-renderer, #container.ytd-masthead {
    background: rgba(0,0,0,0.45) !important;
    backdrop-filter: blur(4px) saturate(120%) !important;
  }

  /* Slight dark overlay so text is readable over bright wallpapers.
     You can change rgba() alpha (0.0 - 0.6) if you want it lighter/darker. */
  ytd-app::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background: rgba(0,0,0,0.18);
  }

  /* Ensure main content sits above the overlay but remains visually translucent */
  body, ytd-app, #page-manager > * {
    position: relative;
    z-index: 1;
  }

  /* Keep video player backgrounds intact (transparent but not broken) */
  ytd-watch-flexy, ytd-player, ytd-watch-flexy[theater] #player {
    background: transparent !important;
  }

  /* Avoid unexpected white boxes on certain cards */
  .ytd-rich-grid-renderer, .ytd-rich-item-renderer, ytd-grid-renderer, ytd-rich-section-renderer {
    background: transparent !important;
  }

  /* Optional: reduce heavy card shadows */
  .ytd-rich-item-renderer, #items ytd-rich-item-renderer, ytd-grid-renderer {
    box-shadow: none !important;
  }

  /* If something becomes unreadable, increase overlay alpha above (ytd-app::before) */
}
